const raw  = $input.first().json;
const item = raw.body || raw;
if (!item.rule?.id || item.rule?.level === undefined || !item.agent?.name) {
  return [];
}
if (parseInt(item.rule.level) < 3) return [];
return [{ json: item }];

const raw  = $input.first().json;
const item = raw.body || raw;
const seen = new Set(); const iocs = [];
const IP_RE   = /\b(?:(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\b/g;
const HASH_RE = /\b(?:[a-fA-F0-9]{64}|[a-fA-F0-9]{32})\b/g;
const DOMAIN_RE = /\b(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}\b/gi;
function addIoc(v,t){const k=t+':'+v.toLowerCase();if(!seen.has(k)){seen.add(k);iocs.push({value:v,type:t});}}
function scan(text){if(!text||typeof text!=='string')return;for(const m of text.matchAll(IP_RE))addIoc(m[0],'ip');for(const m of text.matchAll(HASH_RE))addIoc(m[0],'hash');for(const m of text.matchAll(DOMAIN_RE))addIoc(m[0],'domain');}
[item.data?.srcip,item.data?.dstip,item.data?.win?.eventdata?.destinationIp,item.agent?.ip].forEach(f=>scan(String(f||'')));
scan(item.full_log||'');scan(JSON.stringify(item.data||{}));
return [{json:{...item,raw_iocs:iocs}}];

const item = $input.first().json;
const raw = item.raw_iocs !== undefined ? item : {};
const iocSrc = item.raw_iocs || [];
const RFC = [/^10\./,/^172\.(1[6-9]|2\d|3[01])\./,/^192\.168\./,/^127\./,/^::1$/];
const NH = 'd41d8cd98f00b204e9800998ecf8427e';
const INT = ['.local','.homelab','.internal','.lan'];
const iocs = iocSrc.filter(ioc=>{
  if(ioc.type==='ip')    return !RFC.some(r=>r.test(ioc.value));
  if(ioc.type==='hash')  return ioc.value.toLowerCase()!==NH;
  if(ioc.type==='domain')return !INT.some(s=>ioc.value.toLowerCase().endsWith(s));
  return true;
});
const {raw_iocs,...rest}=item;
return [{json:{...rest,iocs}}];

const item = $input.first().json;
const crypto = require('crypto');
const ruleId    = String(item.rule?.id||'');
const agentName = String(item.agent?.name||'');
const ts = item.timestamp ? Math.floor(new Date(item.timestamp).getTime()/1000/300) : Math.floor(Date.now()/1000/300);
const dedup_key = crypto.createHash('sha1').update(ruleId+agentName+ts).digest('hex');
return [{json:{
  dedup_key, raw_alert:item,
  rule_id:ruleId, rule_level:parseInt(item.rule?.level||0),
  rule_desc:item.rule?.description||'',
  agent_name:agentName, agent_ip:item.agent?.ip||'',
  username:item.data?.win?.eventdata?.subjectUserName||item.data?.dstuser||'',
  command:item.data?.win?.eventdata?.commandLine||item.data?.command||'',
  iocs:item.iocs||[],
}}];
